PAYLOAD={'variant': {'id': 'AdaRES-Y101', 'package': 'adares_y101_query_ffn_skip', 'config': 'configs_song/model_paper5/adares_y101_query_ffn_skip_res.yaml', 'python_files': {'__init__.py': {'base64': 'IyBBZGFSRVMtWTEwMTogc2hhcmVkIGN1cnJlbnQtcXVlcnkgYnlwYXNzIGJlc2lkZSBjb21wbGV0ZSBvcmlnaW5hbCBxdWVyeSBGRk5zLgpmcm9tIC5pcGRuIGltcG9ydCBJUEROCg==', 'sha256': '55beba745d8073f47a0cdf8d1a73d02dd79be4ee3ab60a9f712cb138b55a8d93'}, 'backbone.py': {'base64': '', 'sha256': '57db8747d3c38136f568837d70e75ceea23e101900679db4931724ecb57665ca'}, 'dec.py': {'base64': '', 'sha256': '21d5055b87e5232026a525c2c81e1f5c09d4f7605a5061e821fa6dacc34cb5fd'}, 'ipdn.py': {'base64': '', 'sha256': '55160dfb062353054f6d2d5a09d971a6dc779be2e8fe34e6906187576a623ad9'}, 'loss.py': {'base64': '', 'sha256': '9e6e5925523114caba6213d181b11181abd2820b292730999986b068816046d1'}, 'sample_model.py': {'base64': '', 'sha256': '674e7ef698c6e81ed1c35f14680e1ec748f5c783ed879a6ca72f099b6450bc36'}}, 'config_data': {'base64': '', 'sha256': '1a170434f63da98e10f59c5b17473cde5cf3ff6be0e4381e2771f322853ffa03'}}, 'parent_config': 'configs_song/model_paper5/adares_w2_pointmass_competition_res.yaml', 'goal_sha256': '4b0d4443a0c38a297a2b9022f4756f6992cf956d7a89374990c0e0fc60224f5a', 'parent_dec_lf_sha256': '7e60c1cecfc8fa7809f7c836fa6fef1366806bd23c08e2890508ea26a711acac', 'train_source_lf_sha256': '04afc00889dc58e439197a04be50457664a7906d42d7badfdc96033f9d99b41e'}
"""CPU original model/TRAIN loading and stage-private recurrent fusion normalization controls."""
import base64
import hashlib
import importlib
import importlib.util
import json
from pathlib import Path
import sys
import gorilla
import torch
from torch import nn
import yaml

assert P['physical_gpu'] is None and not torch.cuda.is_initialized()
torch.set_num_threads(2)
root = Path(P['root'])
stage = Path(P['output']).with_suffix('')
assert not stage.exists()
stage.mkdir()
row = PAYLOAD['variant']
package = stage / row['package']
package.mkdir()
for name, value in row['python_files'].items():
    data = base64.b64decode(value['base64'])
    assert hashlib.sha256(data).hexdigest() == value['sha256']
    (package / name).write_bytes(data)
config_path = stage / Path(row['config']).name
data = base64.b64decode(row['config_data']['base64'])
assert hashlib.sha256(data).hexdigest() == row['config_data']['sha256']
config_path.write_bytes(data)
assert yaml.safe_load(config_path.read_text()) == yaml.safe_load((root / PAYLOAD['parent_config']).read_text())
native = importlib.import_module('train')
assert hashlib.sha256(Path(native.__file__).read_bytes().replace(b'\r\n', b'\n')).hexdigest() == PAYLOAD['train_source_lf_sha256']
cfg = gorilla.Config.fromfile(str(config_path))
assert cfg.train.seed == 1999 and cfg.train.epochs == 30
assert cfg.dataloader.train.batch_size == 2 and cfg.model.sampling_module.num_proposal == 128
assert cfg.model.dec.num_layer == 6 and cfg.model.dec.iter_pred
assert cfg.data.train.training and cfg.data.train.prefix == 'train'
namespace = 'ipdn.model_paper5.' + row['package']
importlib.import_module('ipdn.model_paper5')
assert namespace not in sys.modules
spec = importlib.util.spec_from_file_location(namespace, str(package / '__init__.py'), submodule_search_locations=[str(package)])
module = importlib.util.module_from_spec(spec)
sys.modules[namespace] = module
spec.loader.exec_module(module)
Candidate = native.resolve_model_class(str(config_path))
assert Candidate is module.IPDN
gorilla.set_random_seed(cfg.train.seed)
model = Candidate(**cfg.model)
assert all(p.device.type == 'cpu' for p in model.parameters())
logger = importlib.import_module('ipdn.utils').get_root_logger()
native.load_shape_compatible_pretrain(model, cfg.train.pretrain, logger)
dataset = native.resolve_train_dataset(str(config_path), cfg.data.train.copy(), logger)
gorilla.set_random_seed(cfg.train.seed)
batch = dataset.collate_fn([dataset[0], dataset[1]])
assert len(batch['scan_ids']) == 2 and len(batch['ann_ids']) >= 2
assert torch.isfinite(batch['feats']).all()
model.train(True)
assert model.training and model.text_encoder.training
assert all(not p.requires_grad for p in model.text_encoder.parameters())
assert all(m.training for m in model.modules() if isinstance(m, nn.BatchNorm1d))
"""Independent sampled-seed residual controls, followed by native decoder anchors."""
parameters = sum(parameter.numel() for parameter in model.parameters())
assert parameters == 164695173
parent_path = root / 'ipdn/model_paper5/adares_w2_pointmass_competition/dec.py'
assert hashlib.sha256(parent_path.read_bytes().replace(b'\r\n', b'\n')).hexdigest() == PAYLOAD['parent_dec_lf_sha256']
parent_module = importlib.import_module('ipdn.model_paper5.adares_w2_pointmass_competition.dec')
dec_module = importlib.import_module(namespace + '.dec')
controls = []
for dtype in (torch.float32, torch.float64):
    torch.manual_seed(1999)
    rng = torch.get_rng_state().clone()
    layer = dec_module.QueryFFNSkip(7).to(dtype=dtype)
    assert torch.equal(rng, torch.get_rng_state())
    generated, seeds = [torch.randn(2, 5, 7, dtype=dtype, requires_grad=True) for _ in range(2)]
    anchor = layer(generated, seeds)
    assert torch.equal(anchor, generated)
    gradients = torch.autograd.grad(anchor.sum(), (generated, seeds, layer.weight))
    assert torch.equal(gradients[0], torch.ones_like(generated))
    assert torch.equal(gradients[1], torch.zeros_like(seeds))
    assert torch.isfinite(gradients[2]).all() and gradients[2].abs().max() > 0
    with torch.no_grad():
        layer.weight.copy_((torch.arange(49, dtype=dtype).reshape(7, 7) - 24) / 49)
        value = layer(generated, seeds)
        reference = torch.empty_like(value, dtype=torch.float64)
        for b in range(2):
            for i in range(5):
                for d in range(7):
                    reference[b, i, d] = generated[b, i, d].double() + sum(
                        seeds[b, i, k].double() * layer.weight[k, d].double() for k in range(7))
        tolerance = 128 * torch.finfo(dtype).eps
        torch.testing.assert_allclose(value.double(), reference, rtol=tolerance, atol=tolerance)
        order = torch.tensor([3, 1, 4, 0, 2])
        torch.testing.assert_allclose(layer(generated[:, order], seeds[:, order]), value[:, order],
                                     rtol=tolerance, atol=tolerance)
        assert torch.equal(layer(generated.flip(0), seeds.flip(0)), value.flip(0))
        perm = torch.tensor([3, 1, 6, 0, 2, 5, 4])
        other = dec_module.QueryFFNSkip(7).to(dtype=dtype)
        other.weight.copy_(layer.weight[perm][:, perm])
        torch.testing.assert_allclose(other(generated[:, :, perm], seeds[:, :, perm]), value[:, :, perm],
                                     rtol=tolerance, atol=tolerance)
        assert torch.equal(layer(generated, torch.zeros_like(seeds)), generated)
        assert not torch.equal(layer(torch.zeros_like(generated), seeds), torch.zeros_like(generated))
        dirty = seeds.clone()
        dirty[:, 2] += 1
        changed = layer(generated, dirty)
        assert torch.equal(changed[:, [0, 1, 3, 4]], value[:, [0, 1, 3, 4]])
        assert not torch.equal(changed[:, 2], value[:, 2])
        assert torch.isfinite(layer(generated * 1e4, seeds * 1e4)).all()
    gradients = torch.autograd.grad(layer(generated, seeds).square().mean(), (generated, seeds, layer.weight))
    assert all(torch.isfinite(gradient).all() and gradient.abs().max() > 0 for gradient in gradients)
    with torch.no_grad():
        layer.weight.zero_()
        assert torch.equal(layer(generated, seeds), anchor)
    controls.append(dict(dtype=str(dtype), no_RNG=True, zero_identity_and_input_gradients_exact=True,
        independent_scalar_full_query_projection=True, joint_slot_batch_channel_permutations=True,
        zero_seed_preserves_generated=True, zero_generated_receives_seed=True,
        current_query_intervention_is_slot_local=True, both_input_and_parameter_gradients_finite_nonzero=True,
        large_finite_inputs_finite=True, exact_zero_restoration=True))

kwargs = dict(cfg.model.dec, sampling_module=cfg.model.sampling_module, in_channel=cfg.model.media)
torch.manual_seed(1999); parent = parent_module.DEC(**kwargs); rng = torch.get_rng_state().clone()
torch.manual_seed(1999); decoder = dec_module.DEC(**kwargs)
assert torch.equal(rng, torch.get_rng_state())
assert all(torch.equal(v, decoder.state_dict()[k]) for k,v in parent.state_dict().items())
decoder.load_state_dict(model.dec.state_dict())
parent.load_state_dict({k:v for k,v in decoder.state_dict().items() if not k.startswith('query_ffn_skip.')})
torch.manual_seed(1999); lengths = (512, 513); total = sum(lengths)
inputs = dict(x=torch.randn(total,cfg.model.media),fps_seed_sp=torch.arange(cfg.model.fps_num).repeat(2,1),
    batch_offsets=torch.tensor([0,lengths[0],total],dtype=torch.int32),
    lang_feats=torch.randn(2,9,decoder.lang_proj.in_features),lang_masks=torch.ones(2,9,dtype=torch.long),
    sp_pos=torch.randn(total,3),feats_2d=torch.randn(total,decoder.input_proj_2d[0].in_features),
    point_mass=torch.arange(total).remainder(13).float()+1)
inputs['lang_masks'][0,-2:]=0;inputs['lang_feats'][0,-2:]=0
parts = lambda v: list(v['aux_outputs']) + [v]
parent.eval(); decoder.eval()
with torch.no_grad(): baseline = parent(**inputs); output = decoder(**inputs)
assert len(parts(output)) == 7
assert all(torch.equal(a[k],b[k]) for a,b in zip(parts(baseline),parts(output)) for k in ('masks','scores','indis'))

def input_gradients(net):
    feed = dict(inputs); names = ('x','lang_feats','feats_2d')
    for key in names: feed[key] = inputs[key].clone().requires_grad_()
    value = net(**feed)
    loss = sum(p[k].square().mean() for p in parts(value) for k in ('masks','scores','indis'))
    return torch.autograd.grad(loss,tuple(feed[k] for k in names))
for a,b in zip(input_gradients(parent),input_gradients(decoder)):
    torch.testing.assert_allclose(a,b,rtol=1e-5,atol=1e-6)


"""Causal bypass and two synthetic updates with the same pending native callbacks."""
parent.zero_grad(set_to_none=True)
decoder.zero_grad(set_to_none=True)
with torch.no_grad():
    decoder.query_ffn_skip.weight[0, 1] = .25
    changed = decoder(**inputs)
    assert all(torch.equal(parts(changed)[0][k], parts(baseline)[0][k]) for k in ('masks','scores','indis'))
    assert not torch.allclose(parts(changed)[1]['masks'], parts(baseline)[1]['masks'])
    assert not torch.allclose(changed['masks'], baseline['masks'])
    active = decoder.query_ffn_skip.forward
    decoder.query_ffn_skip.forward = lambda generated, seed: generated
    bypassed = decoder(**inputs)
    assert all(torch.equal(a[key], b[key]) for a, b in zip(parts(baseline), parts(bypassed))
               for key in ('masks', 'scores', 'indis'))
    decoder.query_ffn_skip.forward = active
    decoder.query_ffn_skip.weight.zero_()
model.dec = decoder
optimizer = gorilla.build_optimizer(model, cfg.optimizer)
head, residual = decoder.indi_embedding, decoder.query_ffn_skip
step_rows, path_rows, state = [], [], {}
original_prediction = decoder.prediction_head
"""The same six original-FFN/parallel-input callbacks for CPU and native TRAIN."""
def reset_state():
    state.clear()
    state.update(predictions=[], masks=[], gates=[], indicators=[], norms=[], coarse=0,
                 fusion=[], ffn_inputs=[], ffn_outputs=[], adapted=[], features=None, padding=None, mass=None)


def capture_initial(module, args, value):
    assert module is model.dec.query_generator and 'initial' not in state and value.requires_grad
    state['initial'] = value


def capture_mask(module, args, value):
    assert module is model.dec.x_mask and 'mask_base' not in state and value.requires_grad
    value.retain_grad()
    state['mask_base'] = value


def capture_fusion(module, args, value):
    assert module is model.dec.norm_qqa and len(state['fusion']) == len(state['adapted']) < 6
    assert value.requires_grad and value.shape[-1] == 256
    value.retain_grad()
    state['fusion'].append(value)


def before_ffn(module, args):
    index = len(state['ffn_inputs'])
    assert index == len(state['adapted']) < 6 and module is model.dec.qqa_ffn_layers[index]
    assert args[0] is state['fusion'][index] and args[0].requires_grad
    state['ffn_inputs'].append(args[0])


def after_ffn(module, args, value):
    index = len(state['ffn_outputs'])
    assert module is model.dec.qqa_ffn_layers[index] and args[0] is state['ffn_inputs'][index]
    assert value.requires_grad
    value.retain_grad()
    state['ffn_outputs'].append(value)


def capture_skip(module, args, value):
    index = len(state['adapted'])
    assert module is residual and len(args) == 2 and index < 6
    base, current = args
    assert base is state['ffn_outputs'][index] and current is state['ffn_inputs'][index]
    assert base.requires_grad and current.requires_grad and value.requires_grad
    torch.testing.assert_allclose(value.double(), base.double() + current.double() @ module.weight.double(), rtol=1e-5, atol=1e-6)
    assert torch.equal(value, base + current @ module.weight)
    value.retain_grad()
    state['adapted'].append(value)
    nonzero = bool(torch.count_nonzero(module.weight))
    delta = float((value - base).abs().max())
    assert nonzero == bool(len(step_rows)) and (delta > 0 if nonzero else delta == 0)
    path_rows.append(dict(step=len(step_rows), stage=index, weight_nonzero=nonzero, query_delta_max=delta,
        original_full256_FFN_input_identity=True, complete_original_FFN_output_identity=True,
        original_shared_fusion_norm_consumed=True, both_inputs_undetached=True,
        float64_full_query_projection_reference=True, prediction_consumes_adapted_query=False,
        original_static_mask_preserved=False))


def checked_prediction(query, features, padding):
    index = len(state['predictions'])
    if index == 0:
        assert query is state['initial'] and not state['adapted']
        expected, expected_padding = model.dec.get_batches(state['mask_base'], state['batch_offsets_expected'])
        assert torch.equal(features, expected) and torch.equal(padding, expected_padding)
        state['features'], state['padding'] = features, padding
    else:
        assert query is state['adapted'][index - 1] and len(state['adapted']) == index
        path_rows[-1]['prediction_consumes_adapted_query'] = True
        path_rows[-1]['original_static_mask_preserved'] = True
    assert features is state['features'] and padding is state['padding']
    state['predictions'].append(query)
    value = original_prediction(query, features, padding)
    state['masks'].append(value[1])
    expected = (value[1].sigmoid() < .5) | padding.unsqueeze(1)
    expected[expected.all(-1)] = False
    expected = expected | padding.unsqueeze(1)
    assert torch.equal(value[2], expected) and not value[2].requires_grad
    state['gates'].append(value[2])
    return value


def before_coarse(module, args):
    index = state['coarse']
    assert module is model.dec.qia_layers[index] and args[3] is state['gates'][-1]
    state['coarse'] += 1


def before_indicator(module, args):
    assert module is head and args[0] is state['predictions'][-1] and args[1] is state['masks'][-1]
    assert args[2] is state['padding']
    if not state['indicators']:
        state['mass'] = args[3]
    assert args[3] is state['mass'] and not args[3].requires_grad
    state['indicators'].append(len(state['predictions']) - 1)


def capture_query_norm(module, args, value):
    assert module is head.query_norm and args[0] is state['predictions'][-1]
    assert args[0].requires_grad and value.requires_grad
    state['norms'].append(True)


def gradient_record():
    assert len(state['predictions']) == len(state['masks']) == len(state['gates']) == 7
    assert state['indicators'] == list(range(7)) and state['norms'] == [True] * 7 and state['coarse'] == 6
    assert all(len(state[k]) == 6 for k in ('fusion', 'ffn_inputs', 'ffn_outputs', 'adapted'))
    active = [p.grad for p in model.parameters() if p.grad is not None]
    assert active and all(torch.isfinite(g).all() for g in active)
    assert all(p.grad is None for p in model.text_encoder.parameters())
    hg = [p.grad for p in head.parameters() if p.grad is not None]
    assert len(hg) == 10 and all(torch.isfinite(g).all() for g in hg)
    original = [p for m in model.dec.qqa_ffn_layers for p in m.parameters()]
    assert len(original) == 36 and all(p.grad is not None and torch.isfinite(p.grad).all() for p in original)
    assert all(p.grad is not None and torch.isfinite(p.grad).all() for p in model.dec.norm_qqa.parameters())
    assert state['mask_base'].grad is not None and torch.isfinite(state['mask_base'].grad).all()
    for k in ('fusion', 'ffn_inputs', 'ffn_outputs', 'adapted'):
        assert all(v.grad is not None and torch.isfinite(v.grad).all() for v in state[k])
    gradient = residual.weight.grad
    assert gradient is not None and torch.isfinite(gradient).all() and gradient.abs().max() > 0
    return dict(all_finite=True, tensors=len(active), indicator_tensors=10, indicator_calls=7, prediction_calls=7,
        query_norm_consumption_calls=7, coarse_gate_consumers=6, query_FFN_skip_calls=6, original_query_FFN_calls=6,
        original_query_FFN_parameter_tensors=36, full_input_base_adapted_and_original_FFN_gradients_finite=True,
        original_shared_fusion_norm_gradients_finite=True, static_mask_gradients_finite=True,
        frozen_text_encoder_preserved=True, new_gradient_max=float(gradient.abs().max()))


def check_response_rows(rows):
    import math
    assert len(rows) == 12
    for i, row in enumerate(rows):
        step, stage = divmod(i, 6)
        assert type(row['step']) is int and row['step'] == step and type(row['stage']) is int and row['stage'] == stage
        assert type(row['weight_nonzero']) is bool and row['weight_nonzero'] == bool(step)
        for k in ('original_full256_FFN_input_identity', 'complete_original_FFN_output_identity',
                  'original_shared_fusion_norm_consumed', 'both_inputs_undetached', 'float64_full_query_projection_reference',
                  'prediction_consumes_adapted_query', 'original_static_mask_preserved'):
            assert row[k] is True, k
        assert math.isfinite(row['query_delta_max']) and (row['query_delta_max'] > 0 if step else row['query_delta_max'] == 0)


def install_hooks():
    hooks = [model.dec.query_generator.register_forward_hook(capture_initial), model.dec.x_mask.register_forward_hook(capture_mask),
        model.dec.norm_qqa.register_forward_hook(capture_fusion), residual.register_forward_hook(capture_skip),
        head.register_forward_pre_hook(before_indicator), head.query_norm.register_forward_hook(capture_query_norm)]
    for m in model.dec.qqa_ffn_layers:
        hooks += [m.register_forward_pre_hook(before_ffn), m.register_forward_hook(after_ffn)]
    hooks.extend(m.register_forward_pre_hook(before_coarse) for m in model.dec.qia_layers)
    return hooks

hooks = install_hooks()
decoder.prediction_head = checked_prediction
try:
    model.train(True)
    for index in range(2):
        reset_state()
        optimizer.zero_grad()
        torch.manual_seed(1999 + index)
        feed = dict(inputs)
        for key in ('x', 'lang_feats', 'feats_2d'):
            feed[key] = inputs[key].clone().requires_grad_()
        state['batch_offsets_expected'] = feed['batch_offsets']
        value = decoder(**feed)
        labels = torch.arange(256).reshape(2, 128).remainder(2).long()
        loss = sum(torch.nn.functional.cross_entropy(part['indis'].reshape(-1, 2), labels.reshape(-1))
            + part['masks'].square().mean() for part in parts(value))
        assert torch.isfinite(loss)
        loss.backward()
        record = gradient_record()
        assert all(feed[key].grad is not None and torch.isfinite(feed[key].grad).all()
                   for key in ('x', 'lang_feats', 'feats_2d'))
        before = residual.weight.detach().clone()
        optimizer.step()
        update = float((residual.weight.detach() - before).abs().max())
        assert update > 0 and torch.isfinite(residual.weight).all()
        record.update(step=index, synthetic_CPU_decoder_loss=float(loss), parameter_update_max=update,
                      decoder_input_gradients_finite=True)
        step_rows.append(record)
    check_response_rows(path_rows)
finally:
    decoder.prediction_head = original_prediction
    for hook in hooks:
        hook.remove()
model.eval()
assert all(not module.training for module in model.modules())
model.train(True)
assert model.training and model.text_encoder.training and not torch.cuda.is_initialized()
Path(P['output']).write_text(json.dumps(dict(
    complete=True, id=row['id'], config=row['config'], goal_sha256=PAYLOAD['goal_sha256'],
    implementation_test_passed=True, full_model_CPU_constructed=True, configured_TRAIN_data_collated=True,
    released_backbone_loaded=True, native_YAML_semantically_unchanged=True, train_eval_train_roundtrip=True,
    points=int(batch['feats'].shape[0]), expressions=len(batch['ann_ids']), parameters=parameters,
    additional_parameters=65536, component_controls=controls, decoder_initial_RNG_and_parent_weights_exact=True,
    decoder_all_stages_anchor_exact=True, decoder_input_gradients_anchor_close=True,
    all_six_complete_original_query_FFNs_verified=True, all_six_shared_current_query_bypasses_verified=True,
    static_mask_and_original_hard_gate_preserved=True, original_shared_head_query_norm_consumption_verified=True,
    initial_readout_exact_and_refined_masks_change=True, exact_bypass_restoration=True,
    synthetic_CPU_decoder_optimizer_steps=2, CPU_decoder_steps=step_rows, CPU_query_FFN_paths=path_rows,
    CUDA_initialized=False, native_smoke_passed=False, native_task_backward=False, native_sparse_forward=False,
    validation_used=False, admission=False,
    limitation='Original CPU YAML/model/pretrain/TRAIN collation plus synthetic decoder checks only; '
        'not native sparse GPU task, admission, trained efficacy or full-data memory proof.')), encoding='utf8')
